5	#ifndef __CC_PHYSICS_DEBUG_DRAW_H__
6	#define __CC_PHYSICS_DEBUG_DRAW_H__
7	
8	#include "base/ccConfig.h"
9	#if CC_USE_PHYSICS
10	
11	#include "chipmunk/chipmunk.h"
12	#include "math/Vec2.h"
13	#include "math/CCGeometry.h"
14	#include "base/ccTypes.h"
15	
16	NS_CC_BEGIN
17	
18	class DrawNode;
19	class PhysicsBody;
20	class PhysicsShape;
21	class PhysicsJoint;
22	class PhysicsWorld;
23	
24	struct PhysicsDebugDrawConfig
25	{
26	    bool drawShapes;
27	    bool drawJoints;
28	    bool drawContacts;
29	    bool drawBoundingBoxes;
30	    bool drawCentersOfMass;
31	    bool drawVelocities;
32	    bool drawSleepState;
33	    Color4F shapeColor;
34	    Color4F jointColor;
35	    Color4F contactColor;
36	    Color4F bbColor;
37	    float lineWidth;
38	};
39	
40	class PhysicsDebugDraw
41	{
42	public:
43	    PhysicsDebugDraw();
44	    ~PhysicsDebugDraw();
45	
46	    bool init(DrawNode* drawNode);
47	    void setConfig(const PhysicsDebugDrawConfig& config);
48	    PhysicsDebugDrawConfig getConfig() const;
49	
50	    void beginDraw();
51	    void endDraw();
52	    void clear();
53	
54	    void drawWorld(PhysicsWorld* world);
55	    void drawBody(PhysicsBody* body);
56	    void drawShape(PhysicsShape* shape);
57	    void drawJoint(PhysicsJoint* joint);
58	
59	    void drawCircleShape(const Vec2& center, float radius, float angle,
60	                         const Color4F& fillColor, const Color4F& outlineColor);
61	    void drawPolygonShape(const Vec2* verts, int count,
62	                          const Color4F& fillColor, const Color4F& outlineColor);
63	    void drawSegmentShape(const Vec2& a, const Vec2& b, float radius,
64	                          const Color4F& color);
65	    void drawBoundingBox(const Rect& bb, const Color4F& color);
66	    void drawContactPoint(const Vec2& point, const Vec2& normal, float depth,
67	                          const Color4F& color);
68	    void drawVelocityVector(const Vec2& pos, const Vec2& vel, const Color4F& color);
69	    void drawCenterOfMass(const Vec2& pos, float radius, const Color4F& color);
70	    void drawSleepIndicator(const Vec2& pos, bool sleeping, const Color4F& color);
71	    void drawPinJoint(const Vec2& anchorA, const Vec2& anchorB, const Color4F& color);
72	    void drawSpringJoint(const Vec2& anchorA, const Vec2& anchorB,
73	                         float restLength, const Color4F& color);
74	    void drawSlideJoint(const Vec2& anchorA, const Vec2& anchorB,
75	                        float minDist, float maxDist, const Color4F& color);
76	
77	    Color4F getShapeColor(PhysicsShape* shape) const;
78	    Color4F getBodyColor(PhysicsBody* body) const;
79	
80	private:
81	    DrawNode* _drawNode;
82	    PhysicsDebugDrawConfig _config;
83	    bool _initialized;
84	};
85	
86	NS_CC_END
87	
88	#endif // CC_USE_PHYSICS
89	#endif // __CC_PHYSICS_DEBUG_DRAW_H__
90
